import React, { useRef, useEffect } from 'react';

const BoundingBoxCanvas = ({ imageUrl, boxes, labelColors, sliderConfidence }) => {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    const image = new Image();
    console.log(image);
    image.onload = () => {
      canvas.width = 640;
      canvas.height = 640;
      context.drawImage(image, 0, 0, 640, 640);
      boxes.forEach(box => {
        const { x_min, y_min, x_max, y_max, class_name, confidence } = box;
        const width = x_max - x_min;
        const height = y_max - y_min;        

        // Optionally, draw the class name and confidence
        if (labelColors[class_name]) {
          context.fillStyle = labelColors[class_name];
          context.strokeStyle = labelColors[class_name];
        }

        context.lineWidth = 2;
        context.strokeRect(x_min, y_min, width, height);
        context.font = '14px Arial';
        context.fillText(`${class_name} ${Number(confidence.toFixed(2))}`, x_min, y_min - 5);
      });
    };

    image.src = imageUrl;
  }, [imageUrl, boxes]);
    return <canvas ref={canvasRef} />;
};

export default BoundingBoxCanvas;
